const items = $input.all();
const norm = (s) => (s || '').toLowerCase().trim();
const dncRows = items.filter(i => i.json.engagement_status && i.json.website && !i.json.icp_result);
const icpRows = items.filter(i => i.json.icp_result && i.json.website && !i.json.engagement_status);
const statusLabels = {account:'Active Account',past_account:'Past Account',past_meeting:'Past Meeting'};
const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const result = [];
items.forEach((item, idx) => {
  if (item.json.icp_result && item.json.website && !item.json.engagement_status) return;
  if (item.json.engagement_status && item.json.website) return;
  const url = norm(item.json.website);
  const dncMatch = dncRows.find(c => norm(c.json.website) === url);
  if (dncMatch) {
    const st = dncMatch.json.engagement_status || 'dnc';
    const label = statusLabels[st] || st;
    let dateStr = '';
    if (dncMatch.json.last_contact_date) {
      const d = new Date(dncMatch.json.last_contact_date);
      if (!isNaN(d)) dateStr = months[d.getMonth()] + ' ' + d.getDate();
    }
    const notesStr = dncMatch.json.notes || '';
    const ae = (notesStr.match(/AE:([^|]+)/) || [])[1];
    const sdr = (notesStr.match(/SDR:([^|]+)/) || [])[1];
    let people = '';
    if (ae && sdr) people = ae.trim() + ' \u2192 ' + sdr.trim();
    else if (ae) people = ae.trim();
    const parts = ['DNC', label];
    if (dateStr) parts.push(dateStr);
    if (people) parts.push(people);
    result.push({
      json: {
        ...item.json,
        _cache_hit: true,
        _dnc_hit: true,
        _from_cache: true,
        _cached_icp_result: 'FAIL',
        _cached_industry: '',
        _cached_hq_country: '',
        _cached_reasoning: parts.join(' \u00B7 '),
      },
      pairedItem: {item: idx},
    });
    return;
  }
  const icpMatch = icpRows.find(c => norm(c.json.website) === url);
  if (icpMatch) {
    result.push({
      json: {
        ...item.json,
        _cache_hit: true,
        _cached_icp_result: icpMatch.json.icp_result,
        _cached_industry: icpMatch.json.industry || '',
        _cached_hq_country: icpMatch.json.hq_country || '',
        _cached_reasoning: icpMatch.json.icp_reasoning || '',
      },
      pairedItem: {item: idx},
    });
    return;
  }
  result.push({json: {...item.json, _cache_hit: false}, pairedItem: {item: idx}});
});
return result;

