const ALLOWED_CODES = ['NQ1','NQ2','NQ3','NQ4','NQ5','NQ6','NQ7','NQ8','NQ9','NQ10','NQ11','NQ12','NQ13','NQ14','NQ15','NQ16'];

if ($json._from_cache) {
  return { json: { ...$json } };
}

const haikuRaw = $json;
const orig = $('Parse Serper').item.json;
let result = {};
try {
  const txt = haikuRaw.output || '';
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) result = JSON.parse(m[0]);
} catch (e) { result = {}; }

const fetchStatus = orig._fetch_status || 'failed';
const website = orig.website || '';
let icp_result = result.icp_result || 'REVIEW';

const rawDisq = Array.isArray(result.disqualifiers) ? result.disqualifiers : [];
const validDisq = rawDisq.filter(d => d && ALLOWED_CODES.includes(d.code));
const invalidDisq = rawDisq.filter(d => !d || !ALLOWED_CODES.includes(d.code));

let icp_reasoning;
if (icp_result === 'FAIL' && validDisq.length > 0) {
  icp_reasoning = validDisq.map(d => `${d.code}: ${d.reason}`).join('\n');
} else {
  icp_reasoning = result.icp_reasoning || 'Could not parse AI response - manual check needed';
}

if (invalidDisq.length > 0) {
  icp_reasoning += `\n[WARNING: invalid code from model: ${invalidDisq.map(d => d && d.code).join(', ')}]`;
}

const knownFromTraining = result.known_from_training || false;
if ((fetchStatus === 'failed' || fetchStatus === 'spa_no_content') && !knownFromTraining) {
  const r = icp_reasoning.toLowerCase();
  if (!r.includes('fetch') && !r.includes('training') && !r.includes('content') && !r.includes('known')) {
    icp_reasoning += ' [website not fetchable]';
  }
}

const scored = {
  website,
  checked_at: new Date(Date.now()+25200000).toISOString().slice(0,19).replace('T',' '),
  company_name: result.company_name || '',
  industry: result.industry || '',
  hq_country: result.hq_country || '',
  icp_result,
  icp_score: 0,
  icp_reasoning,
  icp_fails: validDisq.map(d => d.code).join(', '),
  known_from_training: knownFromTraining,
  _chat_id: orig._chat_id,
  _fetch_status: fetchStatus,
  _total_unique_count: orig._total_unique_count,
  _batch_truncated: orig._batch_truncated,
  source_type: orig.source_type
};
return { json: scored };
